from pathlib import Path
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,PageBreak,Image,Table,TableStyle
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.pagesizes import A4
root=Path(__file__).resolve().parent.parent
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='BulletText',fontSize=10.5,leading=16,spaceAfter=9,leftIndent=13,firstLineIndent=-10,textColor=colors.HexColor('#334155')))
styles['Title'].textColor=colors.HexColor('#172554');styles['Heading1'].textColor=colors.HexColor('#312e81');styles['Heading2'].textColor=colors.HexColor('#0f766e');styles['BodyText'].leading=15
story=[]
def heading(t):story.append(Paragraph(t,styles['Heading1']));story.append(Spacer(1,8))
def bullets(items):
 for item in items:story.append(Paragraph('• '+item,styles['BulletText']))
def pic(name,caption):
 image=Image(str(root/'docs/images'/name));image.drawHeight= image.imageHeight*490/image.imageWidth;image.drawWidth=490;
 if image.drawHeight>280: image.drawWidth*=280/image.drawHeight;image.drawHeight=280
 story.extend([Spacer(1,8),image,Paragraph(caption,styles['Caption'] if 'Caption' in styles else styles['BodyText'])])
def page():story.append(PageBreak())
heading('CareerGuide')
story.append(Paragraph('CareerCompass: project guide and end-to-end workflow',styles['Title']))
story.append(Paragraph('Prepared 30 October 2026 • Plain-language handover',styles['BodyText']))
bullets(['<b>Purpose:</b> help Indian students explore study choices after Class 10 and Class 12, discover careers and plan their next steps.','<b>What changed:</b> the original Lovable foundation now has a connected career directory, interest assessment, visual roadmaps, downloadable PDFs, saved careers, account backup and an AI companion.','<b>Identity:</b> the website is CareerCompass. Its original Lovable project name is Bright Paths India; this is why confirmation emails use that name.','<b>Where it runs:</b> the updated website currently runs locally at http://127.0.0.1:5174. A GitHub update saves source code; it does not by itself confirm a successful production deployment.'])
pic('home.png','Actual local website: home page.')
page();heading('1. What a student can do')
bullets(['<b>Home:</b> start with After 10th or After 12th guidance. These options remain on the home page instead of taking extra navigation space.','<b>Careers:</b> search 19 career pathways, filter by category and education stage, save a career directly from its card and compare 2-3 careers by work, skills and pathway.','<b>Assessment:</b> answer eight interest questions. Matching interest tags produce up to six suggestions. This is a simple guidance tool, not an AI prediction or a validated psychological assessment.','<b>Roadmaps:</b> search with live suggestions (including UI/UX), use Search or Enter, pick a career, tick completed milestones and download an illustrated colour PDF. Two example pathways are shown.','<b>Saved and history:</b> bookmarks and up to 20 assessment results stay in the current browser.','<b>Resources:</b> links to SWAYAM, Bharat Skills and National Career Service, plus a course-selection checklist. Contact and About were removed at your request.','<b>Exams:</b> 21 existing exam records with search, stage filters and official links. Later visual and AI changes did not intentionally change the exam feature.'])
pic('careers.png','Actual local website: career discovery and direct save controls.')
page();heading('2. The backend: what is connected to what?')
rows=[['Component','Role in the project'],['React + TypeScript','The pages and interactive controls students see.'],['TanStack Start + Vite','Routing, local development, production builds and server functions.'],['Supabase Auth','Account signup, email confirmation, login, password recovery and sessions.'],['Supabase PostgreSQL','Cloud tables for profiles and account-plan backups.'],['Groq: GPT-OSS 120B','Generates career-guidance text replies.'],['Groq: Whisper Turbo','Converts recorded microphone audio into question text.'],['Browser storage','Stores bookmarks, assessment history, language and roadmap progress locally.'],['ReportLab / Python','Generates the 19 illustrated downloadable roadmap PDF files.'],['Lovable / GitHub','Original project environment and versioned source-code repository.']]
t=Table(rows,colWidths=[150,340]);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#172554')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.HexColor('#eef2ff'),colors.white]),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('FONTSIZE',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),12),('BOTTOMPADDING',(0,0),(-1,-1),12)]));story.append(t)
heading('Simple system flow')
bullets(['<b>Student browser → website:</b> pages show the career dataset and collect questions or planning actions.','<b>Website → Supabase:</b> authenticate the student and read/write only the permitted account data.','<b>Website server → Groq → website:</b> the server sends career context and recent conversation; Groq returns a reply.','<b>Microphone → server → Groq transcription → text box:</b> the student reviews the text before sending the question.','<b>Roadmap → PDF link:</b> download an existing file from public/roadmaps. The chat does not generate custom attachments.'])
page();heading('3. Account and AI workflows')
heading('Signup and login')
bullets(['1. A student enters their name, email, a new CareerCompass password, study stage and language, with the required acknowledgement.','2. Supabase creates the account and sends a confirmation email. The normal email link verifies ownership; we do not bypass authentication tables.','3. After confirming, the student logs in with the CareerCompass password, not automatically their Gmail password.','4. Supabase issues a session. The app uses its token for protected pages and server requests.','5. Profile shows the student name, language and stage. Password recovery sends a recovery link and provides a new-password page. Delivery and redirect settings must still be checked for the final production host.'])
heading('Text conversation')
bullets(['1. The signed-in student writes a question. The request goes to an authenticated server function.','2. Input validation limits question length and recent history. Longer assistant answers have a separate allowance so a long reply does not break the next turn.','3. The server reads GROQ_API_KEY privately and sends the question, recent turns and draft career context to Groq. The configured model is openai/gpt-oss-120b.','4. The reply appears in chat. Provider limits and network failures produce readable messages. Questions are sent to Groq; conversation history is held in page memory and clears on refresh.','5. The assistant explains options and next steps. The quiz creates an interest shortlist; these are different roles. PDF requests return a polite limitation and point to Roadmaps without an extra Groq call.'])
heading('Voice conversation')
bullets(['Record a short question (up to 45 seconds), then stop. The microphone tracks are released.','Audio goes through the authenticated server to whisper-large-v3-turbo. The student reviews the transcript before asking the guide.','A spoken question plus an AI answer usually uses two Groq requests. Read reply aloud uses browser speech synthesis rather than another Groq request. Microphone permissions and available device voices still depend on the browser.'])
page();heading('4. Roadmaps, saving and account backup')
pic('roadmap.png','Actual local website: milestone journey with progress and PDF download.')
bullets(['<b>Local first:</b> Save career writes a career slug into browser storage. Roadmap checkboxes store completed pathway steps. Assessment results store a bounded recent history.','<b>Cloud backup:</b> Profile has Save plan to account and Restore account plan. Saving replaces the previous cloud backup; restoring replaces this browser’s plan. This is explicit backup/restore, not automatic real-time merging.','<b>Tables:</b> profiles holds account profile information. student_plans stores bookmarks, progress, history and update time, linked to the account user ID.','<b>Access:</b> row-level security on student_plans permits authenticated users to access only their own user_id. The table and policy were checked; live two-account isolation testing remains pending.','<b>Downloads:</b> scripts/generate_roadmaps.py produces the static PDF collection. Regenerate PDFs after changing career pathways so downloads stay consistent.'])
page();heading('5. Work completed in phases')
bullets(['<b>Phase 1 — connected journeys:</b> career cards and details, bookmarking, related exam links, nested route fixes and assessment data adaptation.','<b>Phase 2 — discovery:</b> stage/category/search filtering, career comparison and three sourced vocational options: Fitter, Electrician - Power Distribution and COPA.','<b>Phase 3 — planning:</b> assessment history, career checklists, progress and later explicit account backup/restore.','<b>Phase 4 — usability:</b> recovery pages, revised navigation, bottom-left assistant entry, removed Contact/About and useful Resources.','<b>Phase 5 — assistance:</b> authenticated Groq text chat, server-side key, 120B model connection test, voice transcription, read-aloud and polite PDF limitation.','<b>Visual refinements:</b> live search suggestions, search/compare buttons, milestone cards, illustrations and colour PDF roadmap designs.'])
heading('What was verified - and what is still pending')
bullets(['Recent automated baseline: 22 tests passed and TypeScript passed. Checks cover content references, filtering, comparison, planning storage, recovery requests, mocked AI handling and conversation-history validation.','Production builds passed during development. Groq 120B returned a real test reply. Signup confirmation email was found in Gmail and its normal verification link succeeded for the requested account.','All 19 roadmap PDFs rendered; a sample was visually reviewed. Static download delivery was checked.','Not fully verified: real microphone transcription on all devices, two-account backup isolation, full recovery lifecycle, native Kannada review and complete mobile/accessibility coverage.','Lint cleanup is incomplete: formatting was improved, but explicit-any and development-refresh warnings remain. Do not describe the project as having a clean lint result.','Career guidance remains draft content except where specific official references are supplied. Do not treat admissions advice as guaranteed or current without checking the institution.'])
page();heading('6. File map and handover')
bullets(['<b>src/routes:</b> page screens, including login, signup, careers, assessment, roadmaps and AI guide.','<b>src/data:</b> career/exam/quiz content and the three additional vocational careers.','<b>src/lib/ai-guide.ts:</b> authenticated Groq chat request, prompt context and error handling.','<b>src/lib/voice.ts:</b> authenticated audio-transcription request.','<b>src/integrations/supabase:</b> backend clients, session attachment and authentication middleware.','<b>src/components/site:</b> navigation, save buttons, planning, account sync, voice controls and visual roadmap components.','<b>supabase/migrations:</b> student-plan table and owner-only policy.','<b>public/roadmaps:</b> 19 downloadable PDFs. <b>scripts/generate_roadmaps.py:</b> PDF generation source.','<b>src/test:</b> automated verification. <b>.env:</b> private settings; never upload it. <b>.env.example:</b> blank key placeholders.'])
heading('Run, test and publish')
bullets(['Install dependencies with npm install. Use npm run dev to run locally; the current local address uses port 5174.','Use npm test, npx tsc --noEmit and npm run build before release.','Keep GROQ_API_KEY server-side. The model setting is GROQ_MODEL. Supabase browser settings use its public key; database service credentials must not be shipped to browsers.','GitHub should receive source, migration files and PDF assets, never private environment values, session tokens, node_modules or generated build output.','The requested GitHub repository is naveenkumarbuilds-stack/career-compass. Update it with a new normal commit based on its existing main branch. Never force-push or rewrite the Lovable-connected history.','Publishing still needs a host with server-function support, configured secrets and correct authentication callback URLs. GitHub source and a local server are not the same as a verified public deployment.'])
heading('Official learning resources')
bullets(['SWAYAM: https://swayam.gov.in/','Bharat Skills: https://bharatskill.gov.in/','National Career Service: https://www.ncs.gov.in/'])
def footer(c,doc):
 c.setStrokeColor(colors.HexColor('#cbd5e1'));c.line(40,35,555,35);c.setFillColor(colors.HexColor('#64748b'));c.setFont('Helvetica',8);c.drawString(40,23,'CareerGuide | CareerCompass project handover | 30 October 2026');c.drawRightString(555,23,str(doc.page))
SimpleDocTemplate(str(root/'docs/careerguide.pdf'),pagesize=A4,leftMargin=45,rightMargin=45,topMargin=40,bottomMargin=48,title='CareerGuide - CareerCompass end-to-end workflow',author='CareerCompass').build(story,onFirstPage=footer,onLaterPages=footer)
print('Saved docs/careerguide.pdf')

